// Approximate NOAA fractional-year solar geometry, north-based clockwise azimuth.
// https://gml.noaa.gov/grad/solcalc/solareqns.PDF
import {rad,bearing,normAngle,transform,rectPolygon,convexHull,pointInside,FOREST_BEARING} from './geometry.js?v=15';
export const SOLAR_DEFAULT={date:'2026-06-21',minutes:16*60,lat:56.098333,lng:36.595,tz:3,show:true,shadows:true,forest:true,treeHeight:20};
const deg=n=>n*180/Math.PI,clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function validDate(v){return typeof v==='string'&&/^20\d{2}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;}
export function cleanSolar(v={}){const s={...SOLAR_DEFAULT};if(validDate(v?.date))s.date=v.date;for(const [k,a,b] of [['minutes',0,1439],['lat',-70,70],['lng',-180,180],['treeHeight',0,40]])if(Number.isFinite(v?.[k])&&v[k]>=a&&v[k]<=b)s[k]=v[k];for(const k of ['show','shadows','forest'])if(typeof v?.[k]==='boolean')s[k]=v[k];return s;}
export function solarPosition(date,minutes,lat=SOLAR_DEFAULT.lat,lng=SOLAR_DEFAULT.lng,tz=3){
 const [year,month,day]=date.split('-').map(Number),doy=Math.round((Date.UTC(year,month-1,day)-Date.UTC(year,0,1))/86400000)+1,days=year%4===0&&(year%100!==0||year%400===0)?366:365,g=2*Math.PI/days*(doy-1+(minutes/60-12)/24);
 const eq=229.18*(.000075+.001868*Math.cos(g)-.032077*Math.sin(g)-.014615*Math.cos(2*g)-.040849*Math.sin(2*g));
 const dec=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g);
 const solarMinutes=((minutes+eq+4*lng-60*tz)%1440+1440)%1440,H=rad(solarMinutes/4-180),phi=rad(lat),altitude=deg(Math.asin(clamp(Math.sin(phi)*Math.sin(dec)+Math.cos(phi)*Math.cos(dec)*Math.cos(H),-1,1))),azimuth=(deg(Math.atan2(Math.sin(H),Math.cos(H)*Math.sin(phi)-Math.tan(dec)*Math.cos(phi)))+180+360)%360;
 return {altitude,azimuth,daylight:altitude>0};
}
export const timeLabel=minutes=>{if(!Number.isFinite(minutes))return '—';const t=Math.max(0,Math.min(1439,Math.round(minutes)));return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');};
const dayCache=new Map();
export function solarDay(s){const key=[s.date,s.lat,s.lng].join(',');if(dayCache.has(key))return dayCache.get(key);const samples=[];for(let t=0;t<=1440;t+=10)samples.push({minutes:t,...solarPosition(s.date,t,s.lat,s.lng)});let sunrise=null,sunset=null,highest=samples[0];const root=(a,b)=>{for(let i=0;i<15;i++){const mid=(a+b)/2;if(solarPosition(s.date,mid,s.lat,s.lng).altitude>-.833)b=mid;else a=mid;}return (a+b)/2;};for(let i=1;i<samples.length;i++){const a=samples[i-1],b=samples[i];if(b.altitude>highest.altitude)highest=b;if(a.altitude<-.833&&b.altitude>=-.833)sunrise=root(a.minutes,b.minutes);if(a.altitude>=-.833&&b.altitude<-.833){let lo=a.minutes,hi=b.minutes;for(let j=0;j<15;j++){const mid=(lo+hi)/2;if(solarPosition(s.date,mid,s.lat,s.lng).altitude>=-.833)lo=mid;else hi=mid;}sunset=(lo+hi)/2;}}const result={samples,sunrise,sunset,noon:highest.minutes,dayLength:sunrise!==null&&sunset!==null?sunset-sunrise:0};if(dayCache.size>30)dayCache.clear();dayCache.set(key,result);return result;}
export function facadeLight(house,s){const intervals=[];let start=null,total=0;for(let t=0;t<=1440;t+=5){const sun=solarPosition(s.date,t,s.lat,s.lng),front=sun.altitude>0&&Math.cos(rad(normAngle(sun.azimuth-bearing(house))))>.001;if(front&&start===null)start=t;if(!front&&start!==null){intervals.push([start,t]);total+=t-start;start=null;}}if(start!==null){intervals.push([start,1440]);total+=1440-start;}return {intervals,minutes:total};}
export function sunVector(azimuth){const a=rad(azimuth-(FOREST_BEARING-180));return [Math.cos(a),Math.sin(a)];}
export function shadowPolygon(poly,height,sun){if(sun.altitude<=0||height<=0)return [];const length=Math.min(200,height/Math.tan(rad(sun.altitude))),v=sunVector(sun.azimuth),shift=[-v[0]*length,-v[1]*length];return convexHull([...poly,...poly.map(p=>[p[0]+shift[0],p[1]+shift[1]])]);}
export function shadowScene(project,s){const sun=solarPosition(s.date,s.minutes,s.lat,s.lng),center=transform([1,0],project.house),body={...project.house,x:center[0],y:center[1],w:6,h:10},polys=[];if(sun.daylight){if(s.shadows){polys.push({kind:'house',points:shadowPolygon(rectPolygon(body),project.house.height||2.7,sun)});polys.push({kind:'shed',points:shadowPolygon(rectPolygon(project.shed),project.shed.height||2.5,sun)});}if(s.forest&&s.treeHeight>0)polys.push({kind:'forest',points:shadowPolygon([[-1.5,-8],[0,-8],[0,30],[-1.5,30]],s.treeHeight,sun)});}let shade=0,count=0;for(let i=0;i<8;i++)for(let j=0;j<4;j++){const p=transform([-3.75+j*.5,-4.375+i*1.25],project.house);count++;if(polys.some(poly=>poly.points.length&&pointInside(p,poly.points)))shade++;}return {sun,polys,shadeFraction:shade/count,shadowLength:sun.altitude>0?(project.house.height||2.7)/Math.tan(rad(sun.altitude)):null,front:sun.daylight&&Math.cos(rad(normAngle(sun.azimuth-bearing(project.house))))>0};}
